// This file is generated by AI.

// 行内差异区域控制器的测试。
//
// 三条语义都会**静默**出错 (不抛异常, 只是行为不对), 因此值得固定下来: 同时只展开一个 (多个会让
// 滚动高度跳变, 用户正在看的那一行跑掉); 同一行再点一次是收起; 内容一变就收起 (view zone 按行号
// 锚定, 打字之后它指向的内容已经不对了)。
//
// 不引入 jsdom: 只给 `document.createElement` 一个最小替身, 走的是真实代码路径。

import { beforeEach, describe, expect, it, vi } from 'vitest';

import { createInlineDiffZoneController, type InlineDiffRegion } from '../src/editor/inline-diff-zone';

/** 最小 DOM 替身: 只要 `createElement` / `className` / `textContent` / `append` / `addEventListener`。 */
function installFakeDocument(): void {
  class FakeElement {
    className = '';
    textContent = '';
    children: FakeElement[] = [];
    append(...nodes: FakeElement[]) {
      this.children.push(...nodes);
    }
    addEventListener() {}
  }
  vi.stubGlobal('document', { createElement: () => new FakeElement() });
}

/** 最小 Monaco 替身: 记下增删的 view zone, 并能触发内容变化。 */
function createFakeEditor(lineCount = 100) {
  const zones = new Map<string, { afterLineNumber: number; domNode: unknown }>();
  const listeners: Array<() => void> = [];
  let nextId = 0;

  const editor = {
    getModel: () => ({ getLineCount: () => lineCount }),
    changeViewZones: (callback: (accessor: unknown) => void) => {
      callback({
        addZone: (zone: { afterLineNumber: number; domNode: unknown }) => {
          nextId += 1;
          const id = `zone-${nextId}`;
          zones.set(id, zone);
          return id;
        },
        removeZone: (id: string) => {
          zones.delete(id);
        },
      });
    },
    onDidChangeModelContent: (listener: () => void) => {
      listeners.push(listener);
      return { dispose: () => listeners.splice(listeners.indexOf(listener), 1) };
    },
  };

  return {
    editor: editor as never,
    zones,
    /** 模拟用户打字 */
    type: () => listeners.slice().forEach((listener) => listener()),
  };
}

const REGION: InlineDiffRegion = {
  rows: [
    { kind: '-', text: 'bgm:01.wav;' },
    { kind: '+', text: 'bgm:02.wav;' },
  ],
  anchor: 5,
};

describe('createInlineDiffZoneController', () => {
  beforeEach(() => {
    installFakeDocument();
  });

  it('展开后有一个 view zone，行号被记下', async () => {
    const { editor, zones } = createFakeEditor();
    const controller = createInlineDiffZoneController({ editor, loadRegion: async () => REGION });

    await controller.toggle(5);

    expect(zones.size).toBe(1);
    expect(controller.openLine()).toBe(5);
  });

  it('展开的 zone 高度按行数给（两行差异占两行）', async () => {
    const { editor, zones } = createFakeEditor();
    const controller = createInlineDiffZoneController({ editor, loadRegion: async () => REGION });

    await controller.toggle(5);

    expect([...zones.values()][0]).toMatchObject({ afterLineNumber: 5 });
    expect(controller.openLine()).toBe(5);
  });

  it('同一行再点一次是收起', async () => {
    const { editor, zones } = createFakeEditor();
    const controller = createInlineDiffZoneController({ editor, loadRegion: async () => REGION });

    await controller.toggle(5);
    await controller.toggle(5);

    expect(zones.size).toBe(0);
    expect(controller.openLine()).toBeNull();
  });

  it('点另一行时先收掉旧的（同时只展开一个）', async () => {
    const { editor, zones } = createFakeEditor();
    const controller = createInlineDiffZoneController({ editor, loadRegion: async () => REGION });

    await controller.toggle(5);
    await controller.toggle(9);

    expect(zones.size).toBe(1);
    expect(controller.openLine()).toBe(9);
  });

  it('内容一变就收起（行号会漂移）', async () => {
    const { editor, zones, type } = createFakeEditor();
    const controller = createInlineDiffZoneController({ editor, loadRegion: async () => REGION });

    await controller.toggle(5);
    expect(zones.size).toBe(1);

    type();

    expect(zones.size).toBe(0);
    expect(controller.openLine()).toBeNull();
  });

  it('取不到差异时不展开、也不抛错', async () => {
    const { editor, zones } = createFakeEditor();
    const controller = createInlineDiffZoneController({ editor, loadRegion: async () => null });

    await controller.toggle(5);

    expect(zones.size).toBe(0);
    expect(controller.openLine()).toBeNull();
  });

  it('后端出错时安静地不展开（不该因为 git 出错打断编辑）', async () => {
    const { editor, zones } = createFakeEditor();
    const controller = createInlineDiffZoneController({
      editor,
      loadRegion: async () => {
        throw new Error('not a git repository');
      },
    });

    await expect(controller.toggle(5)).resolves.toBeUndefined();
    expect(zones.size).toBe(0);
  });

  it('空差异不展开（没有可展示的内容就别占一行位置）', async () => {
    const { editor, zones } = createFakeEditor();
    const controller = createInlineDiffZoneController({
      editor,
      loadRegion: async () => ({ rows: [], anchor: 5 }),
    });

    await controller.toggle(5);

    expect(zones.size).toBe(0);
  });

  it('行号超出文档时不动手', async () => {
    const { editor, zones } = createFakeEditor(10);
    const controller = createInlineDiffZoneController({ editor, loadRegion: async () => REGION });

    await controller.toggle(999);

    expect(zones.size).toBe(0);
  });

  it('慢请求不会覆盖后一次点击的结果', async () => {
    const { editor, zones } = createFakeEditor();
    // 用对象字段而不是裸的 `let`: 赋值发生在 Promise 回调里, 裸变量会被 TS 的控制流分析收窄成 null
    const slow: { resolve?: (region: InlineDiffRegion) => void } = {};

    const controller = createInlineDiffZoneController({
      editor,
      loadRegion: (line) =>
        line === 5 ? new Promise<InlineDiffRegion>((resolve) => (slow.resolve = resolve)) : Promise.resolve(REGION),
    });

    const pending = controller.toggle(5);
    await controller.toggle(9); // 后点的那一行先返回
    slow.resolve?.(REGION);
    await pending;

    // 展开的应该还是后点的 9, 而不是慢请求回来的 5
    expect(controller.openLine()).toBe(9);
    expect(zones.size).toBe(1);
  });

  it('dispose 会收起 zone 并停止响应内容变化', async () => {
    const { editor, zones, type } = createFakeEditor();
    const controller = createInlineDiffZoneController({ editor, loadRegion: async () => REGION });

    await controller.toggle(5);
    controller.dispose();

    expect(zones.size).toBe(0);
    expect(() => type()).not.toThrow();
  });
});
